# Micro_V5 (flyer). Generated by tools/hy_dino.py config from the measured shape; edit freely.
NAME = 'Micro_V5'
PARTS = ['Body', 'Head', 'Tail', 'LegL', 'LegR', 'WingL', 'WingR']
BUDGET = {'Body': 520, 'Head': 480, 'Tail': 200, 'LegL': 220, 'LegR': 220, 'WingL': 260, 'WingR': 260}
HEAD_Z, TAIL_Y, LEG_Z, LEG_X = 1.81, -0.35, 0.95, 0.12
LEGS = (0.06, 0.96)
LIMB_X, LIMB_Z = 0.42, (0.6, 1.8)

def label(c):
    if c.z > HEAD_Z:
        return 'Head'
    if c.y < TAIL_Y and c.z > LEG_Z * 0.6:
        return 'Tail'
    if abs(c.x) > LIMB_X and LIMB_Z[0] < c.z < LIMB_Z[1]:
        return 'Wing' + ('L' if c.x < 0 else 'R')
    if c.z < LEG_Z and abs(c.x) > LEG_X and LEGS[0] < c.y < LEGS[1]:
        return 'Leg' + ('L' if c.x < 0 else 'R')
    return 'Body'

CUTS = [
    ((0, 0, HEAD_Z), (0, 0, 1), None),
    ((0, TAIL_Y, 0), (0, 1, 0), ((-9, -9, LEG_Z * 0.6), (9, 9, HEAD_Z))),
    ((LIMB_X, 0, 0), (1, 0, 0), ((0, -9, LIMB_Z[0]), (9, 9, LIMB_Z[1]))),
    ((0, 0, LEG_Z), (0, 0, 1), ((LEG_X - 0.05, LEGS[0], 0), (9, LEGS[1], LEG_Z + 0.05))),
    ((LEG_X, 0, 0), (1, 0, 0), ((0, LEGS[0], 0), (9, LEGS[1], LEG_Z + 0.05))),
]

